#!/usr/bin/env python3
"""Generate/check the maintainer path map and statically resolve payload references offline."""
from __future__ import annotations

import argparse
from collections import Counter
import fnmatch
import hashlib
import json
from pathlib import Path, PurePosixPath
import posixpath
import re

INVENTORY = ".github/distribution/payload.v1.tsv"
MAP = ".github/distribution/maintainer-map.v1.json"
PAYLOAD = ".github/distribution/payload"
TEXT_SUFFIXES = {".md", ".sh", ".toml", ".yml"}
# Delimiters, rather than a filename whitelist, preserve unknown substitutions
# and suffixes so that an unresolved reference cannot pass as a valid prefix.
REFERENCE = re.compile(r'''\.(?:github|agents|codex)/[^\s`'"()|;]*''')
MARKDOWN_LINK = re.compile(r"\]\(([^\s()]+)\)")
SKILL_RESOURCE = re.compile(r"(?<![\w/])(?:templates|scripts)/[^\s`'\"()|;]+")

# Exact source/token exceptions only: no namespace-wide exemption. These are
# adopter artifacts or an explicit exclusion, never missing shipped helpers.
# Each tuple is (category, reason, {source: {references}}).
ALLOWLIST = (
    ("context", "Adopter-created intake topics and illustrative source records.", {
        ".agents/skills/context-collection/SKILL.md": {
            ".github/docs/context/<topic>/", ".github/docs/context/device-pairing/",
            ".github/docs/context/line-integration/"},
        ".agents/skills/project-onboarding/SKILL.md": {".github/docs/context/<topic>/"},
        ".github/connectors/builtin.md": {".github/docs/context/<topic>/"},
        ".github/docs/context/README.md": {".github/docs/context/<topic>/"},
        ".github/docs/agreements/glossary.md": {".github/docs/context/device-pairing/"},
        ".github/docs/agreements/non-goals.md": {".github/docs/context/device-pairing/INDEX.md"},
        ".github/docs/agreements/requirements.md": {
            ".github/docs/context/device-pairing/interview-2026-07-01.md"},
    }),
    ("adr-template", "Naming template for a new adopter decision, not the shipped ADR template.", {
        ".agents/skills/context-distillation/SKILL.md": {
            ".github/docs/agreements/adr/ADR-####-<slug>.md"},
    }),
    ("scoped-instruction", "Placeholder for an adopter-defined instruction file.", {
        ".agents/skills/context-distillation/SKILL.md": {
            ".github/instructions/<area>.instructions.md"},
    }),
    ("adopter-ci", "Application CI is owned by the adopter and is not installed by the kit.", {
        ".agents/skills/project-onboarding/SKILL.md": {
            ".github/workflows/ci.yml", ".github/workflows/"},
        ".agents/skills/retro/SKILL.md": {".github/workflows/"},
        ".github/scripts/tuning-status.sh": {".github/workflows/ci.yml"},
        ".github/scripts/check-task-ritual.sh": {
            ".github/workflows/*.yml", ".github/workflows/*.yaml"},
    }),
    ("codeowners", "Optional adopter governance file, including its GET API reference.", {
        ".github/scripts/tuning-status.sh": {".github/CODEOWNERS"},
        ".github/scripts/setup-ruleset.sh": {".github/CODEOWNERS?ref=$DEFAULT_BRANCH"},
    }),
    ("source-registry", "Generated by setup-sources.sh in the adopter repository.", {
        ".github/scripts/setup-sources.sh": {".github/docs/context/SOURCES.md"},
    }),
    ("excluded-tests", "The onboarding Skill explicitly excludes contributor-only test internals.", {
        ".agents/skills/project-onboarding/SKILL.md": {".github/scripts/tests/"},
    }),
)


def inventory_map(root):
    """The TSV is the sole generator input; its byte digest detects any drift."""
    data = (root / INVENTORY).read_bytes()
    files = []
    seen = set()
    for number, line in enumerate(data.decode("utf-8").splitlines(), 1):
        if not line or line.startswith("#"):
            continue
        fields = line.split("\t")
        if len(fields) != 3:
            raise ValueError(f"{INVENTORY}:{number}: expected destination/class/sha256")
        destination, kind, digest = fields
        path = PurePosixPath(destination)
        if (path.is_absolute() or ".." in path.parts or str(path) != destination
                or destination in {"", "."} or destination in seen
                or kind not in {"engine", "tuned", "instance", "seed"}
                or not re.fullmatch(r"[0-9a-f]{64}", digest)):
            raise ValueError(f"{INVENTORY}:{number}: invalid or duplicate entry {destination!r}")
        seen.add(destination)
        files.append({"installed_path": destination, "payload_path": f"{PAYLOAD}/{destination}"})
    if not files:
        raise ValueError(f"{INVENTORY}: empty inventory")
    return {"schema": "maintainer-map/v1", "source": INVENTORY,
            "source_sha256": hashlib.sha256(data).hexdigest(), "files": files}


def unique_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key {key!r}")
        result[key] = value
    return result


def load_map(root, expected):
    try:
        record = json.loads((root / MAP).read_text(encoding="utf-8"), object_pairs_hook=unique_keys)
    except (OSError, UnicodeError, ValueError) as error:
        raise ValueError(f"{MAP}: cannot read map: {error}") from error
    if not isinstance(record, dict) or record.get("schema") != "maintainer-map/v1":
        raise ValueError(f"{MAP}: expected schema maintainer-map/v1")
    entries = record.get("files")
    if not isinstance(entries, list):
        raise ValueError(f"{MAP}: files must be a list")
    mapped = {}
    for index, row in enumerate(entries):
        if (not isinstance(row, dict) or set(row) != {"installed_path", "payload_path"}
                or not isinstance(row["installed_path"], str)
                or not isinstance(row["payload_path"], str)):
            raise ValueError(f"{MAP}: files[{index}]: malformed entry")
        installed, payload = row["installed_path"], row["payload_path"]
        if installed in mapped:
            raise ValueError(f"{MAP}: duplicate installed_path {installed!r}")
        if payload != f"{PAYLOAD}/{installed}":
            raise ValueError(f"{MAP}: {installed!r}: payload_path must be {PAYLOAD}/{installed}")
        mapped[installed] = payload
    destinations = {row["installed_path"] for row in expected["files"]}
    if set(mapped) != destinations:
        missing, extra = sorted(destinations - mapped.keys()), sorted(mapped.keys() - destinations)
        raise ValueError(f"{MAP}: installed_path set differs from {INVENTORY}; "
                         f"missing={missing}, extra={extra}; regenerate with --write")
    if record != expected:
        raise ValueError(f"{MAP}: stale or noncanonical map for {INVENTORY}; regenerate with --write")
    return mapped


def references(source, content):
    """Yield textual occurrences; a brace group counts once, all targets must resolve.

    Namespace prefixes embedded in shell strings are installed-root references.
    Relative Markdown links resolve in full from the source directory, never by
    taking only an embedded namespace suffix. URLs and anchors are outside scope.
    This is a static path check, not a shell evaluator or a general link checker.
    """
    for number, line in enumerate(content.splitlines(), 1):
        links = list(MARKDOWN_LINK.finditer(line)) if source.endswith(".md") else []

        def in_link(match):
            return any(link.start(1) <= match.start() < link.end(1) for link in links)

        for match in REFERENCE.finditer(line):
            if in_link(match):
                continue
            token = match.group().rstrip(".,:")
            yield number, token, token
        for match in links:
            token = match.group(1)
            if token.startswith("#") or "://" in token:
                continue
            path = token.split("#", 1)[0]
            installed = posixpath.normpath(posixpath.join(posixpath.dirname(source), path))
            yield number, token, installed
        if source.startswith(".agents/skills/"):
            for match in SKILL_RESOURCE.finditer(line):
                if in_link(match):
                    continue
                token = match.group().rstrip(".,:")
                installed = posixpath.normpath(posixpath.join(posixpath.dirname(source), token))
                yield number, token, installed


def glob_matches(path, pattern):
    """Match path components, with '**' as the explicit recursive wildcard."""
    if not pattern:
        return not path
    if pattern[0] == "**":
        return glob_matches(path, pattern[1:]) or bool(path and glob_matches(path[1:], pattern))
    return bool(path and fnmatch.fnmatchcase(path[0], pattern[0])
                and glob_matches(path[1:], pattern[1:]))


def expand_reference(reference):
    # Strip anchors only following a filename, preserving ADR-#### placeholders.
    reference = re.sub(r"(?<=\.md)#[^/]*$", "", reference)
    if "{" not in reference and "}" not in reference:
        return [reference]
    match = re.fullmatch(r"([^{}$]*)\{([\w-]+(?:,[\w-]+)+)\}([^{}]*)", reference)
    if not match:
        raise ValueError("unsupported brace expression or substitution")
    return [match[1] + name + match[3] for name in match[2].split(",")]


def resolve(reference, mapped):
    for target in expand_reference(reference):
        if any(part in {".", ".."} for part in target.split("/")):
            raise ValueError("noncanonical path contains traversal")
        if any(char in target for char in "$<>=#\\"):
            raise ValueError("unrecognized placeholder, substitution or fragment")
        if target in mapped:
            continue
        if target.endswith("/"):
            matches = [path for path in mapped if path.startswith(target)]
        elif any(char in target for char in "*?["):
            # Segment matching prevents '*' from hiding an extra path component.
            parts = target.split("/")
            matches = [path for path in mapped if glob_matches(path.split("/"), parts)]
        else:
            # Skill directory references may omit their trailing slash.
            matches = [path for path in mapped if path.startswith(target + "/")]
        if not matches:
            raise ValueError(f"{target!r} has no mapped file or descendant")


def validate(root, expected):
    mapped = load_map(root, expected)
    errors = []
    for installed, payload in mapped.items():
        path = root / payload
        if not path.is_file() or path.is_symlink() or not path.resolve().is_relative_to((root / PAYLOAD).resolve()):
            errors.append(f"{MAP}: {installed!r}: {payload!r} is not a regular file inside payload")
    count, scanned, allowed = 0, 0, Counter()
    for path in sorted((root / PAYLOAD).rglob("*")):
        if path.suffix not in TEXT_SUFFIXES:
            continue
        source = path.relative_to(root / PAYLOAD).as_posix()
        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            errors.append(f"{PAYLOAD}/{source}: cannot scan text: {error}")
            continue
        scanned += 1
        for line, token, reference in references(source, content):
            count += 1
            exemption = next((category for category, _, sources in ALLOWLIST
                              if token in sources.get(source, set())), None)
            if exemption:
                allowed[exemption] += 1
                continue
            try:
                resolve(reference, mapped)
            except ValueError as error:
                errors.append(f"{PAYLOAD}/{source}:{line}: {token!r}: {error}")
    return errors, count, scanned, allowed


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[2])
    parser.add_argument("--write", action="store_true",
                        help="regenerate the map using only payload.v1.tsv, then validate")
    args = parser.parse_args()
    try:
        expected = inventory_map(args.root)
        if args.write:
            (args.root / MAP).write_text(json.dumps(expected, indent=2) + "\n", encoding="utf-8")
        errors, count, scanned, allowed = validate(args.root, expected)
    except (OSError, UnicodeError, ValueError) as error:
        print(f"ERROR: {error}")
        return 1
    for error in errors:
        print(f"ERROR: {error}")
    if errors:
        return 1
    exceptions = sum(allowed.values())
    print(f"Maintainer map OK: {len(expected['files'])} entries; {count} references checked "
          f"in {scanned} text files ({count - exceptions} resolved, {exceptions} allowlisted).")
    for category, reason, _ in ALLOWLIST:
        if allowed[category]:
            print(f"  allowlist {category}: {allowed[category]} — {reason}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
